import React, { useState } from 'react';
import { View, Text, StatusBar, SafeAreaView, Switch, TouchableOpacity } from 'react-native';
import styled from 'styled-components/native';
import Icon from '@expo/vector-icons/MaterialIcons';
import { colors, spacing, borderRadius } from '../../theme/tokens';

const Container = styled.View`
  flex: 1;
  background-color: ${colors.secondary}; /* Black predominant as requested */
`;

const Header = styled.View`
  padding: ${spacing.md}px;
  padding-top: ${StatusBar.currentHeight || 40}px;
  background-color: ${colors.secondary};
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
`;

const StatusContainer = styled.View`
  flex-direction: row;
  align-items: center;
`;

const StatusLabel = styled.Text`
  color: ${colors.white};
  font-size: 14px;
  margin-right: ${spacing.sm}px;
`;

const AvailabilityText = styled.Text`
  color: ${props => props.active ? colors.primary : colors.textSecondary};
  font-size: 18px;
  font-weight: bold;
`;

const MapView = styled.View`
  flex: 1;
  background-color: #333; /* Darker map for driver */
  justify-content: center;
  align-items: center;
`;

const BottomNav = styled.View`
  height: 70px;
  background-color: ${colors.secondary};
  flex-direction: row;
  justify-content: space-around;
  align-items: center;
  border-top-width: 1px;
  border-top-color: #333;
`;

const NavItem = styled.TouchableOpacity`
  align-items: center;
  opacity: ${props => props.active ? 1 : 0.5};
`;

import { useNavigation } from '@react-navigation/native';

const DriverHomeScreen = () => {
  const navigation = useNavigation();
  const [isAvailable, setIsAvailable] = useState(true);
  const [newRide, setNewRide] = useState(null); // Corrida recebida via API

  // Simulação de Polling para novas corridas
  React.useEffect(() => {
    if (!isAvailable) return;

    // Simula uma nova corrida chegando após 5 segundos
    const timer = setTimeout(() => {
        setNewRide({
            id: 123,
            cliente: 'João Silva',
            distancia: '1.2 km',
            tempo: '4 min',
            valor: 'R$ 14,90',
            destino: 'Av. Paulista, 1000'
        });
    }, 5000);

    return () => clearTimeout(timer);
  }, [isAvailable]);

  const handleAcceptRide = () => {
    // Aqui chamaria api.post('aceitar.php', ...)
    setNewRide(null);
    alert('Corrida Aceita! Navegando para o cliente...');
  };

  return (
    <Container>
      <StatusBar barStyle="light-content" backgroundColor={colors.secondary} />

      <Header>
        <StatusContainer>
          <View>
            <StatusLabel>Disponibilidade:</StatusLabel>
            <AvailabilityText active={isAvailable}>
              {isAvailable ? 'DISPONÍVEL' : 'OFFLINE'}
            </AvailabilityText>
          </View>
          <Switch 
            value={isAvailable} 
            onValueChange={setIsAvailable}
            trackColor={{ false: '#333', true: colors.primary }}
            thumbColor={isAvailable ? colors.white : '#f4f3f4'}
            style={{ marginLeft: 10 }}
          />
        </StatusContainer>

        <TouchableOpacity>
            <Icon name="account-circle" size={40} color={colors.primary} />
        </TouchableOpacity>
      </Header>

      <MapView>
        <Icon name="map" size={120} color="#444" />
        <Text style={{ color: '#666', marginTop: 10 }}>Modo Motorista (Mapa Escuro)</Text>
      </MapView>

      {/* Modal de Nova Corrida - Uber Style Alert */}
      {newRide && (
          <View style={{
              position: 'absolute', bottom: 80, left: 16, right: 16,
              backgroundColor: colors.primary, borderRadius: borderRadius.lg,
              padding: 20, elevation: 10, shadowColor: '#000',
              shadowOffset: { width: 0, height: 5 }, shadowOpacity: 0.3, shadowRadius: 10
          }}>
              <Text style={{ color: colors.white, fontSize: 14, fontWeight: 'bold' }}>NOVA SOLICITAÇÃO!</Text>
              <Text style={{ color: colors.white, fontSize: 24, fontWeight: 'bold', marginVertical: 5 }}>{newRide.valor}</Text>
              <Text style={{ color: colors.white, fontSize: 16 }}>{newRide.cliente} • {newRide.distancia} ({newRide.tempo})</Text>
              <Text style={{ color: 'rgba(255,255,255,0.8)', fontSize: 14, marginTop: 5 }}>Destino: {newRide.destino}</Text>

              <TouchableOpacity 
                onPress={handleAcceptRide}
                style={{ backgroundColor: colors.white, padding: 15, borderRadius: 10, marginTop: 15, alignItems: 'center' }}
              >
                  <Text style={{ color: colors.primary, fontWeight: 'bold', fontSize: 18 }}>ACEITAR CORRIDA</Text>
              </TouchableOpacity>

              <TouchableOpacity onPress={() => setNewRide(null)} style={{ marginTop: 10, alignItems: 'center' }}>
                  <Text style={{ color: 'rgba(255,255,255,0.6)', fontSize: 14 }}>Recusar</Text>
              </TouchableOpacity>
          </View>
      )}

      <BottomNav>
        <NavItem active>
            <Icon name="home" size={28} color={colors.white} />
        </NavItem>
        <NavItem>
            <Icon name="list-alt" size={28} color={colors.white} />
        </NavItem>
        <NavItem>
            <Icon name="speed" size={32} color={colors.primary} />
        </NavItem>
        <NavItem>
            <Icon name="history" size={28} color={colors.white} />
        </NavItem>
        <NavItem>
            <Icon name="assessment" size={28} color={colors.white} />
        </NavItem>
      </BottomNav>
    </Container>
  );
};

export default DriverHomeScreen;
